"""Fixed screenline development comparisons and route/demand coverage diagnostics."""
from pathlib import Path
import os,sys,json,datetime as dt
os.environ.setdefault('OPENBLAS_NUM_THREADS','1')
import numpy as np,pandas as pd
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'src/analyses'))
from evaluate_normal_vehicle_baseline_v1 import metric,sha
P=ROOT/'data/processed/three_ward_normal_vehicle_time_v1';R=ROOT/'data/exp/estimation/three_ward_normal_vehicle_time_v1';REPAIR=ROOT/'data/processed/three_ward_normal_vehicle_repair_v1';OLD=ROOT/'data/processed/three_ward_normal_vehicle_baseline_v1';M=ROOT/'data/processed/three_ward_motor_flood_access_v1'
def load(p):
 with np.load(p,allow_pickle=False)as z:return{k:z[k]for k in z.files}
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False,default=lambda v:v.item()if isinstance(v,np.generic)else str(v))+'\n')
def main():
 prep=json.loads((R/'preparation_summary.json').read_text());assert all(prep['checks'].values());d=pd.read_csv(REPAIR/'passage_comparison.csv',dtype={'count_authority_code':str,'count_unit_id':str,'observation_section_id':str});d=d[d.arm.eq('C_topology_multi')].copy();d['arm']='D_distance_multi';cross=pd.read_csv(OLD/'census_comparison_eligibility.csv',dtype={'count_authority_code':str,'count_unit_id':str});roadmap={(r.count_authority_code,r.count_unit_id):np.array([int(j)for j in str(r.matched_road_indices).split('|')])for r in cross[cross.eligible_observation_comparison.eq(True)].itertuples()};pr=load(M/'road_projection.npz');inv=pd.read_csv(M/'road_inventory.csv');parts=[d];runchecks={};route=[];reach=[];costs=load(P/'time_costs.npz');baseline=load(REPAIR/'C_topology_multi_flows.npz');last_reached=None;reach_equal=True;optimality={};cost_bindings={};usage=[]
 # Compare source-road class passage-distance; not census counts or distinct trips.
 def collect_usage(arm,flux):
  h=inv.highway.to_numpy()[pr['arc_to_road']];core=inv.inside_core.to_numpy()[pr['arc_to_road']].astype(bool)
  for b,branch in enumerate(['base_no_remote_remote','plus_conditional_chord_through']):
   for t,period in [(0,'daily'),(4,'daytime12h')]:
    for scope,sm in [('whole_road_halo',np.ones(len(h),bool)),('core_intersecting_roads',core)]:
     for cls in sorted(set(h)):
      mask=sm&(h==cls);usage.append({'arm':arm,'branch':branch,'period':period,'scope':scope,'highway':cls,'candidate_passage_km':float(np.sum(flux[b,t,mask]*pr['length_m'][mask])/1000)})
 collect_usage('D_distance_multi',baseline['arc_flow'])
 for i,arm in enumerate(['T1_class_time','T2_survey_time']):
  check=json.loads((R/(arm+'_validation.json')).read_text());assert check['passed'];runchecks[arm]=check;z=load(P/(arm+'_flows.npz'));collect_usage(arm,z['arc_flow']);rf=np.array([[np.bincount(pr['arc_to_road'],weights=z['arc_flow'][b,t],minlength=len(inv))for t in range(5)]for b in range(2)]);roadreached=np.bincount(pr['arc_to_road'],weights=z['reachable_physical_arcs'],minlength=len(inv))>0;rows=[]
  if last_reached is not None:reach_equal=bool(np.array_equal(last_reached,z['reachable_physical_arcs']))
  last_reached=z['reachable_physical_arcs'];oldcost=np.einsum('bte,e->bt',baseline['arc_flow'],costs['arc_cost_seconds'][i]);newcost=np.einsum('bte,e->bt',z['arc_flow'],costs['arc_cost_seconds'][i]);optimality[arm]=bool(np.all(newcost<=oldcost+np.maximum(1e-5,oldcost*1e-10)));cost_bindings[arm]=bool(np.allclose(newcost/3600,np.array(check['assumed_route_candidate_hours']),rtol=1e-9,atol=1e-6))
  for r in d.itertuples():
   idx=roadmap[(r.count_authority_code,r.count_unit_id)];b=0 if r.branch=='base_no_remote_remote'else 1;t=['daily','hour8','hour10','hour17','daytime12h'].index(r.period);out=r._asdict();out.pop('Index');out['predicted']=float(rf[b,t,idx].sum());out['arm']=arm;rows.append(out)
  parts.append(pd.DataFrame(rows))
  for b,branch in enumerate(['base_no_remote_remote','plus_conditional_chord_through']):
   for t,period in enumerate(['daily','hour8','hour10','hour17','daytime12h']):route.append({'arm':arm,'branch':branch,'period':period,'routed_candidate_trips':float(z['routed'][b,t]),'any_modeled_motorway_trips':float(z['od_any_motorway'][b,t]),'any_core_road_trips':float(z['od_any_core'][b,t]),'assumed_route_candidate_hours':check['assumed_route_candidate_hours'][b][t],'distance_route_hours_under_same_speed_assumption':float(oldcost[b,t]/3600),'candidate_passage_km':check['arc_candidate_km'][b][t]})
  for r in cross[cross.eligible_observation_comparison.eq(True)].itertuples():
   idx=roadmap[(r.count_authority_code,r.count_unit_id)];prediction=float(rf[0,4,idx].sum());reach.append({'arm':arm,'count_authority_code':r.count_authority_code,'count_unit_id':r.count_unit_id,'some_matched_arc_forward_reachable_from_active_origin':bool(roadreached[idx].any()),'all_matched_roads_have_reachable_arc':bool(roadreached[idx].all()),'zero_passages_base12h':prediction<1e-9,'interpretation':'Forward reachability alone is not evidence of a chosen OD path or a complete route through this screenline.'})
 pd.DataFrame(usage).to_csv(P/'road_class_passage_distance.csv',index=False,encoding='utf-8-sig');df=pd.concat(parts,ignore_index=True);df.to_csv(P/'passage_comparison.csv',index=False,encoding='utf-8-sig');pd.DataFrame(route).to_csv(P/'route_usage_and_cost.csv',index=False,encoding='utf-8-sig');pd.DataFrame(reach).to_csv(P/'screenline_reachability.csv',index=False,encoding='utf-8-sig');metrics=[]
 for key,g in df.groupby(['arm','branch','period','comparison_class','evaluation_role'],sort=True):metrics.append(dict(zip(['arm','branch','period','comparison_class','evaluation_role'],key),road_class='all',**metric(g)))
 for key,g in df.groupby(['arm','branch','period','comparison_class','evaluation_role','road_class'],sort=True):metrics.append(dict(zip(['arm','branch','period','comparison_class','evaluation_role','road_class'],key),**metric(g)))
 pd.DataFrame(metrics).to_csv(P/'flow_metrics.csv',index=False,encoding='utf-8-sig');sel=df.branch.eq('base_no_remote_remote')&df.period.eq('daytime12h')&df.comparison_class.eq('small');paired=df[sel].pivot(index=['observation_section_id','count_authority_code','count_unit_id','road_class','evaluation_role','observed'],columns='arm',values='predicted').reset_index();paired.to_csv(P/'paired_screenline_changes.csv',index=False,encoding='utf-8-sig');changes=[]
 for arm in ['D_distance_multi','T1_class_time','T2_survey_time']:
  changes.append({'arm':arm,'all85_zero_screenlines':int((paired[arm]<1e-9).sum()),'all85_absolute_error_improved_vs_distance':int((abs(paired[arm]-paired.observed)<abs(paired.D_distance_multi-paired.observed)-1e-7).sum()),'all85_absolute_error_worsened_vs_distance':int((abs(paired[arm]-paired.observed)>abs(paired.D_distance_multi-paired.observed)+1e-7).sum())})
 bindings=json.loads((P/'input_bindings.json').read_text())['sha256'];hashchecks={p:sha(ROOT/p)==h for p,h in bindings.items()};checks={'preparation_checks_pass':all(prep['checks'].values()),'both_time_assignments_pass':all(x['passed']for x in runchecks.values()),'input_bindings_unchanged':all(hashchecks.values()),'same85screenlines':len(paired)==85,'same_observation_values_all_arms':bool(df.groupby(['count_authority_code','count_unit_id','branch','period','comparison_class'])['observed'].nunique().eq(1).all()),'same_route_feasibility_T1_T2':reach_equal,'time_optimal_cost_not_above_distance_route_cost':all(optimality.values()),'saved_costs_reproduce_reported_route_hours':all(cost_bindings.values()),'no_OD_rescaling':True,'no_independent_holdout_claim':set(df.evaluation_role)=={'development_original_calibration65','development_previously_inspected20'}};dump(R/'validation.json',{'passed':all(checks.values()),'checks':checks,'source_hash_checks':hashchecks,'cost_optimality_checks':optimality});coverage=json.loads((R/'demand_coverage_summary.json').read_text());primary=[m for m in metrics if m['branch']=='base_no_remote_remote'and m['period']=='daytime12h'and m['comparison_class']=='small'];reachsum=[]
 for arm,g in pd.DataFrame(reach).groupby('arm'):
  reachsum.append({'arm':arm,'some_arc_unreachable_screenlines':int((~g.some_matched_arc_forward_reachable_from_active_origin).sum()),'zero_but_some_arc_forward_reachable_screenlines':int((g.zero_passages_base12h&g.some_matched_arc_forward_reachable_from_active_origin).sum())})
 summary={'completed_utc':dt.datetime.now(dt.timezone.utc).isoformat(),'stage':'Static distance/time route-choice development comparison;not congestion assessment','preparation':prep,'coverage':coverage,'core_source_routed_fraction':coverage['core_routed_daily']/coverage['core_source_touching_daily'],'primary_small12h_base_metrics':primary,'screenline_changes':changes,'reachability_diagnostics':reachsum,'route_summaries':runchecks,'checks_passed':sum(checks.values()),'checks_total':len(checks),'independent_validation':False,'people_counts':False,'new_hydraulics':False,'congestion_or_queue_response':False};dump(R/'summary.json',summary);print(json.dumps({'primary20':[m for m in primary if m['evaluation_role']=='development_previously_inspected20'],'zero_counts':changes,'reachability':reachsum,'checks':checks},ensure_ascii=False,indent=2))
 if not all(checks.values()):raise SystemExit('Time comparison integrity failure')
if __name__=='__main__':main()
